accTitle: System Requirements
accDescr: Full SysML-style requirement diagram

requirement SRD-001 {
  id: SRD-001
  text: The system shall respond within 100ms.
  risk: high
  verifymethod: test
}

functionalRequirement FUNC-001 {
  id: FUNC-001
  text: Process user input.
  risk: medium
  verifymethod: demonstration
}

designConstraint CONST-001 {
  id: CONST-001
  text: Must use standard protocols.
  risk: low
  verifymethod: inspection
}

element test_suite {
  type: verification
  docref: test-plan-v2
}

element simulator {
  type: simulation
  docref: sim-spec
}

test_suite - verifies -> SRD-001
SRD-001 - satisfies -> FUNC-001
FUNC-001 - derives -> CONST-001
test_suite - contains -> simulator

